import{_ as o,o as t,c as a,a3 as s}from"./chunks/framework.B8xISX-C.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting"},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),n={name:"guide/troubleshooting.md"};function d(r,e,i,c,h,l){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page lists the common issues and what they mean.</p><p><code>check</code>, the INSTALLED tab and dev mode print the same issues. Each names the severity, a code, the mod and file, the JSON path in the file and what was expected:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error role-size me.example:assets/roles.json $.roles[0].file: assets/title.png is 100x50; menus.title.backdrop is 640x480</span></span></code></pre></div><p><code>check</code> stops at the first stage that fails, so fixing one issue can show the next.</p><h2 id="tool-and-setup" tabindex="-1">Tool and setup <a class="header-anchor" href="#tool-and-setup" aria-label="Permalink to &quot;Tool and setup&quot;">​</a></h2><p><strong><code>npx carina-modkit</code> does not start.</strong> It needs Node.js 22 or newer. <code>node --version</code> prints yours.</p><p><strong><code>pack</code> writes different bytes on another machine.</strong> Node.js versions compress differently. The <code>packageHash</code> that <code>check</code> prints is the mod&#39;s identity and does not change.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p><strong><code>missing-dependency</code>.</strong> A mod named in <code>dependencies</code> is not there. <code>check</code>, <code>run</code> and <code>pack</code> look for it in the other folders of <code>mods/</code>; <code>--with &lt;folder&gt;</code> names another. In the game, INSTALL in ONLINE CATALOG installs a catalog mod&#39;s dependencies with it. A mod imported from a file needs them installed or imported too.</p><p><strong><code>dependency-version</code>.</strong> The other mod is there but its version is outside <code>range</code>. See <a href="/carina-mod-template/guide/dependencies">Dependencies and compatibility</a>.</p><h2 id="patches" tabindex="-1">Patches <a class="header-anchor" href="#patches" aria-label="Permalink to &quot;Patches&quot;">​</a></h2><p><strong><code>patch-expect-failed</code></strong> (<code>expected roundLimit = 50, found 60</code>). A game update or another mod changed the value your row builds on. Check that your change still makes sense against the new value, then update <code>expect</code>.</p><p><strong><code>patch-no-match</code>.</strong> The record, anchor or value of the row does not exist. Check the key against the catalog&#39;s page in <a href="/carina-mod-template/reference/">Reference</a>. <code>optional: true</code> skips a row whose target may be gone.</p><p><strong><code>unknown-field</code></strong> (<code>$.records[0].roundLimitX</code>). The <code>path</code> of a <code>set</code> row names a field the record does not have. Check the path against the catalog&#39;s page.</p><p><strong><code>patch-type-mismatch</code>.</strong> The value of the row is not the type of the field. The field&#39;s type is in the catalog&#39;s page.</p><h2 id="pictures-and-sound" tabindex="-1">Pictures and sound <a class="header-anchor" href="#pictures-and-sound" aria-label="Permalink to &quot;Pictures and sound&quot;">​</a></h2><p><strong><code>role-size</code>.</strong> A picture is not the size its role needs. <a href="/carina-mod-template/reference/roles">Roles</a> lists the size of every role.</p><p><strong><code>role-namespace</code>.</strong> The role is neither a base role nor part of the contract of a race you add. The numbered portrait roles belong to the stock Humans.</p><h2 id="in-the-game" tabindex="-1">In the game <a class="header-anchor" href="#in-the-game" aria-label="Permalink to &quot;In the game&quot;">​</a></h2><p><strong>The mod is not in New Game RULES.</strong> A mod with only pictures, text or sound is a cosmetic pack. Switch it on under LOOK AND SOUND on the INSTALLED tab.</p><p><strong>A saved or multiplayer game refuses the mods.</strong> It was made with mods you lack or have in another version. The game compares rules by hash, not by name. The message lists them. GET FROM CATALOG installs the ones the catalog lists, with the mods they need.</p><p><strong>A save refused after your update.</strong> See <a href="/carina-mod-template/guide/updates">Releasing an update</a>. <code>modMismatch</code> means the rules changed at the same <code>rulesVersion</code>. <code>missingModMigration</code> means the <code>rulesVersion</code> rose without a migration for every step.</p><p><strong>Dev mode does not show your last change.</strong> Firefox and Safari cannot watch a folder. Press FOLDER again after editing.</p><p><strong>Dev mode LOAD does not load an old save.</strong> After a rules change a save made before it no longer matches. Use RESTART.</p>',25)])])}const m=o(n,[["render",d]]);export{g as __pageData,m as default};
